using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // EF Core 9 Cosmos provider no longer supports synchronous I/O by default.
        // Re-enable it for backward compatibility with sync calls (ToList, SaveChanges).
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "BlogDb",
            cosmosOptions => cosmosOptions.AllowSynchronousQueryExecution());
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: Default discriminator property renamed from
            // "Discriminator" to "$type". Existing documents use "Discriminator".
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 2: Default id format changed from "EntityType|Key"
            // to just the raw key. Existing documents use "Blog|<key>" format.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyIdValueGenerator>();
        });

        // Breaking change 3: HasIndex now throws on Cosmos (was silently ignored).
        // Removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
    }
}

// Value generator that preserves the legacy "Blog|<key>" id format
class LegacyIdValueGenerator : Microsoft.EntityFrameworkCore.ValueGeneration.ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(Microsoft.EntityFrameworkCore.ChangeTracking.EntityEntry entry)
        => $"Blog|{Guid.NewGuid()}";
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

